-- GENERATED FILE — DO NOT HAND-EDIT.
--
-- This is a mirror of the schema Alembic actually applies, produced by
-- `uv run alembic upgrade head --sql` (Alembic's offline SQL emission
-- mode) against every migration in alembic/versions/, each of which was
-- autogenerated from src/churn/db/models.py. It is a literal copy of
-- that dump (migration history included, e.g. columns added by ALTER
-- TABLE in a later revision rather than folded into the original CREATE
-- TABLE) rather than a hand-folded "final state" rewrite, so there is no
-- manual transformation step that could itself introduce drift.
--
-- To change the schema: edit src/churn/db/models.py, run
--   uv run alembic revision --autogenerate -m "..."
--   uv run alembic upgrade head --sql > sql/ddl/_regen.sql   (then paste the body in here, delete _regen.sql)
-- Never edit this file directly. Also check the new migration by hand —
-- autogenerate does not reliably detect new CHECK constraints (see
-- DECISIONS.md#autogenerate-misses-check-constraints); this file's
-- feature_snapshots CHECK constraints had to be added to the migration
-- by hand for exactly that reason.
-- See DECISIONS.md#ddl-generated-from-alembic-not-hand-duplicated.

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL,
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Revision 48ccb1be188e: initial schema

CREATE TABLE customers (
    customer_id VARCHAR(20) NOT NULL,
    gender VARCHAR(10) NOT NULL,
    senior_citizen BOOLEAN NOT NULL,
    partner BOOLEAN NOT NULL,
    dependents BOOLEAN NOT NULL,
    signup_date DATE NOT NULL,
    source_row_hash VARCHAR(64) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
    PRIMARY KEY (customer_id)
);

CREATE TABLE ingestion_runs (
    run_id SERIAL NOT NULL,
    source_url VARCHAR(500) NOT NULL,
    sha256 VARCHAR(64) NOT NULL,
    row_count INTEGER NOT NULL,
    loaded_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
    PRIMARY KEY (run_id),
    CONSTRAINT uq_ingestion_runs_sha256 UNIQUE (sha256)
);

CREATE TABLE churn_labels (
    customer_id VARCHAR(20) NOT NULL,
    churned BOOLEAN NOT NULL,
    churn_date DATE,
    censored_as_of DATE NOT NULL,
    PRIMARY KEY (customer_id),
    CONSTRAINT ck_churn_labels_churn_date_consistency CHECK ((churned = false AND churn_date IS NULL) OR (churned = true AND churn_date IS NOT NULL)),
    FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);

-- feature_snapshots: created here with only the spine (keys + label);
-- typed feature columns are added by revision 18765fcc5439 below — see
-- DECISIONS.md#feature_snapshots-schema-staged-across-phases.
CREATE TABLE feature_snapshots (
    snapshot_id SERIAL NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    reference_date DATE NOT NULL,
    feature_set_version VARCHAR(20) NOT NULL,
    label_churn_next_30d BOOLEAN,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
    PRIMARY KEY (snapshot_id),
    FOREIGN KEY(customer_id) REFERENCES customers (customer_id),
    CONSTRAINT uq_feature_snapshots_customer_ref_version UNIQUE (customer_id, reference_date, feature_set_version)
);

CREATE INDEX ix_feature_snapshots_reference_date ON feature_snapshots (reference_date);

CREATE TABLE predictions (
    prediction_id SERIAL NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    reference_date DATE NOT NULL,
    model_version VARCHAR(50) NOT NULL,
    probability NUMERIC(6, 5) NOT NULL,
    risk_band VARCHAR(10) NOT NULL,
    shap_top3 JSONB NOT NULL,
    scored_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
    actual_churned BOOLEAN,
    label_matured_at TIMESTAMP WITH TIME ZONE,
    PRIMARY KEY (prediction_id),
    CONSTRAINT ck_predictions_risk_band CHECK (risk_band IN ('low', 'medium', 'high')),
    CONSTRAINT ck_predictions_probability_range CHECK (probability >= 0 AND probability <= 1),
    FOREIGN KEY(customer_id) REFERENCES customers (customer_id),
    CONSTRAINT uq_predictions_customer_ref_model UNIQUE (customer_id, reference_date, model_version)
);

CREATE TABLE subscriptions (
    subscription_id SERIAL NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    contract_type VARCHAR(20) NOT NULL,
    phone_service BOOLEAN NOT NULL,
    multiple_lines VARCHAR(20) NOT NULL,
    internet_service VARCHAR(20) NOT NULL,
    online_security VARCHAR(20) NOT NULL,
    online_backup VARCHAR(20) NOT NULL,
    device_protection VARCHAR(20) NOT NULL,
    tech_support VARCHAR(20) NOT NULL,
    streaming_tv VARCHAR(20) NOT NULL,
    streaming_movies VARCHAR(20) NOT NULL,
    paperless_billing BOOLEAN NOT NULL,
    payment_method VARCHAR(30) NOT NULL,
    monthly_charges NUMERIC(10, 2) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    PRIMARY KEY (subscription_id),
    CONSTRAINT ck_subscriptions_contract_type CHECK (contract_type IN ('Month-to-month', 'One year', 'Two year')),
    CONSTRAINT ck_subscriptions_end_after_start CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT ck_subscriptions_monthly_charges_nonneg CHECK (monthly_charges >= 0),
    FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);

-- Only one "current" subscription per customer at a time — see
-- DECISIONS.md#synthetic-service-attributes-are-static-for-now.
CREATE UNIQUE INDEX ux_subscriptions_active_customer ON subscriptions (customer_id) WHERE end_date IS NULL;

CREATE TABLE support_tickets (
    ticket_id SERIAL NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    created_date DATE NOT NULL,
    resolved_date DATE,
    category VARCHAR(30) NOT NULL,
    priority VARCHAR(10) NOT NULL,
    satisfaction_score SMALLINT,
    PRIMARY KEY (ticket_id),
    CONSTRAINT ck_support_tickets_priority CHECK (priority IN ('low', 'medium', 'high')),
    CONSTRAINT ck_support_tickets_resolved_after_created CHECK (resolved_date IS NULL OR resolved_date >= created_date),
    CONSTRAINT ck_support_tickets_satisfaction_range CHECK (satisfaction_score IS NULL OR satisfaction_score BETWEEN 0 AND 5),
    FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);

CREATE INDEX ix_support_tickets_customer_date ON support_tickets (customer_id, created_date);

CREATE TABLE billing_events (
    event_id SERIAL NOT NULL,
    customer_id VARCHAR(20) NOT NULL,
    subscription_id INTEGER NOT NULL,
    event_date DATE NOT NULL,
    event_type VARCHAR(20) NOT NULL,
    amount NUMERIC(10, 2) NOT NULL,
    PRIMARY KEY (event_id),
    CONSTRAINT ck_billing_events_event_type CHECK (event_type IN ('charge', 'payment_failed', 'refund')),
    CONSTRAINT ck_billing_events_amount_nonneg CHECK (amount >= 0),
    FOREIGN KEY(customer_id) REFERENCES customers (customer_id),
    FOREIGN KEY(subscription_id) REFERENCES subscriptions (subscription_id)
);

CREATE INDEX ix_billing_events_customer_date ON billing_events (customer_id, event_date);

